// n8n Code node: "Normalize Blog Data"
// Runs after AI Agent. Combines AI output with LinkedIn row (imageLink).

const ai = $('AI Agent').first().json.output || {};
const linkedin = $('Get row(s)').first().json;

function slugify(title) {
  return String(title || '')
    .trim()
    .replace(/[^\w\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .slice(0, 80);
}

function extractUrls(text) {
  return [...String(text || '').matchAll(/https?:\/\/[^\s\])>"']+/g)].map((m) => m[0]);
}

function pickSourceArticleUrl(aiUrl, postContent, idea) {
  if (aiUrl) return aiUrl;
  const fromPost = extractUrls(postContent);
  if (fromPost.length) return fromPost[fromPost.length - 1];
  const fromIdea = extractUrls(idea);
  return fromIdea[0] || '';
}

function parseTags(val) {
  if (Array.isArray(val)) return val.map((t) => String(t).trim()).filter(Boolean);
  if (typeof val === 'string') {
    const s = val.trim();
    if (!s) return [];
    if (s.startsWith('[')) {
      try {
        const parsed = JSON.parse(s);
        if (Array.isArray(parsed)) return parsed.map((t) => String(t).trim()).filter(Boolean);
      } catch (e) {
        /* fall through */
      }
    }
    return s.split(',').map((t) => t.trim()).filter(Boolean);
  }
  return [];
}

function publishDateFromLinkedIn(row) {
  const raw = row.updatedAt || row.createdAt || '';
  if (raw) {
    const d = new Date(raw);
    if (!isNaN(d.getTime())) return d.toISOString().slice(0, 10);
  }
  return new Date().toISOString().slice(0, 10);
}

const slug = (ai.slug || slugify(ai.title) || 'blog-post').replace(/\.html$/i, '');
const tags = parseTags(ai.tags);
// Never trust AI for publish date — use LinkedIn row timestamp (when post was created/published).
const date = publishDateFromLinkedIn(linkedin);
const featured_image = `/images/blog/${slug}.jpg`;
const url = `/blog/${slug}.html`;
const author = ai.authorName || 'Alec Asgari';
const author_image = '/assets/images/team/alec-asgari-author.webp';

const sourceArticleUrl = pickSourceArticleUrl(
  ai.sourceArticleUrl,
  linkedin.postContent,
  linkedin.idea
);
const linkedinPostUrl = ai.linkedinPostUrl || linkedin.LinkedInURL || '';

const output = {
  slug,
  title: ai.title || 'Untitled',
  excerpt: ai.excerpt || '',
  category: ai.category || 'Business',
  date,
  featured_image,
  image: featured_image,
  url,
  content: ai.content || '',
  tags,
  authorName: author,
  meta_description: ai.excerpt || '',
  sourceArticleUrl,
  linkedinPostUrl,
};

return [{
  json: {
    output,
    slug,
    title: output.title,
    excerpt: output.excerpt,
    category: output.category,
    date,
    content: output.content,
    imageLink: linkedin.imageLink || '',
    linkedin_row_id: linkedin.id,
    tags,
    tags_json: JSON.stringify(tags),
    featured_image,
    url,
    author,
    author_image,
    status: 'pending',
  },
}];

// n8n Code node: "Prepare Blog Image for GitHub"
// Input: HTTP Request binary (downloaded imageLink)

const norm = $('Normalize Blog Data').first().json;
const slug = norm.slug;
const binaryData = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64String = binaryData.toString('base64');

return [{
  json: {
    slug,
    image_path: `/images/blog/${slug}.jpg`,
    github_path: `images/blog/${slug}.jpg`,
    base64_image: base64String,
    linkedin_row_id: norm.linkedin_row_id,
  },
}];

// n8n Code node: "Prepare Blog HTML for GitHub"
// Keep in sync with scripts/regenerate-blog-pages.js buildPage() — paste this whole file into n8n.

const norm = $('Normalize Blog Data').first().json;
const post = norm.output || {};
const slug = norm.slug || post.slug;
const tags = Array.isArray(post.tags)
  ? post.tags
  : JSON.parse(norm.tags_json || '[]');
const image = norm.featured_image || `/images/blog/${slug}.jpg`;
const url = norm.url || `/blog/${slug}.html`;
const author = norm.author || post.authorName || 'Alec Asgari';
const author_image = norm.author_image || '/assets/images/team/alec-asgari-author.webp';
const content = post.content || $('AI Agent').first().json.output?.content || '';

function esc(s) {
  return String(s || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function inlineMd(text) {
  let s = String(text || '');
  s = s.replace(/\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/g, (_, label, href) => {
    return `%%LINK%%${href}%%LABEL%%${label}%%ENDLINK%%`;
  });
  s = esc(s)
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/`(.+?)`/g, '<code>$1</code>')
    .replace(
      /%%LINK%%([^%]+)%%LABEL%%([^%]+)%%ENDLINK%%/g,
      '<a href="$1" target="_blank" rel="noopener">$2</a>'
    );
  return s;
}

function buildReferencesHtml(data) {
  const source = data.sourceArticleUrl || '';
  const linkedin = data.linkedinPostUrl || '';
  if (!source && !linkedin) return '';

  if (/references/i.test(data.content || '')) return '';

  let html = '<h2>References</h2><ul>';
  if (source) {
    html += `<li><a href="${esc(source)}" target="_blank" rel="noopener">Source article</a></li>`;
  }
  if (linkedin) {
    html += `<li><a href="${esc(linkedin)}" target="_blank" rel="noopener">Original LinkedIn post by Alec Asgari</a></li>`;
  }
  html += '</ul>';
  return html;
}

function mdToHtml(md) {
  const lines = String(md || '').split('\n');
  const out = [];
  let inUl = false;
  let inOl = false;

  function closeUl() {
    if (inUl) {
      out.push('</ul>');
      inUl = false;
    }
  }

  function closeOl() {
    if (inOl) {
      out.push('</ol>');
      inOl = false;
    }
  }

  function closeLists() {
    closeUl();
    closeOl();
  }

  for (const line of lines) {
    const t = line.trim();
    if (!t) {
      closeLists();
      continue;
    }
    if (t.startsWith('## ')) {
      closeLists();
      out.push(`<h2>${inlineMd(t.slice(3))}</h2>`);
      continue;
    }
    if (t.startsWith('### ')) {
      closeLists();
      out.push(`<h3>${inlineMd(t.slice(4))}</h3>`);
      continue;
    }
    if (t.startsWith('- ')) {
      closeOl();
      if (!inUl) {
        out.push('<ul>');
        inUl = true;
      }
      out.push(`<li>${inlineMd(t.slice(2))}</li>`);
      continue;
    }
    const olMatch = t.match(/^\d+\.\s+(.*)$/);
    if (olMatch) {
      closeUl();
      if (!inOl) {
        out.push('<ol>');
        inOl = true;
      }
      out.push(`<li>${inlineMd(olMatch[1])}</li>`);
      continue;
    }
    closeLists();
    out.push(`<p>${inlineMd(t)}</p>`);
  }
  closeLists();
  return out.join('\n');
}

function formatDate(iso) {
  if (!iso) return '';
  const d = new Date(iso.includes('T') ? iso : iso + 'T00:00:00');
  return isNaN(d.getTime()) ? iso : d.toLocaleDateString('en-US');
}

function buildBlogHtml(data, bodyHtml, tagList) {
  const title = data.title || 'Untitled';
  const excerpt = data.excerpt || '';
  const category = data.category || 'Business';
  const date = String(data.date || '').slice(0, 10);
  const pageUrl = `https://alecasgari.com${url}`;

  const tagsHtml = tagList.length
    ? `<div class="blog-tags"><h3 style="width:100%;margin:0 0 0.5rem;font-size:0.9rem">Tags</h3>${tagList
        .map((t) => `<span class="blog-tag">${esc(t)}</span>`)
        .join('')}</div>`
    : '';

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${esc(title)} — Alec Asgari</title>
  <meta name="description" content="${esc(excerpt)}">
  <link rel="canonical" href="${pageUrl}">
  <meta property="og:type" content="article">
  <meta property="og:title" content="${esc(title)}">
  <meta property="og:description" content="${esc(excerpt)}">
  <meta property="og:image" content="https://alecasgari.com${esc(image)}">
  <link rel="shortcut icon" href="/assets/images/logos/favicon.svg">
  <link rel="stylesheet" href="/assets/css/site.css?v=4">
  <link rel="stylesheet" href="/assets/css/blog-detail.css?v=1">
  <script async src="https://www.googletagmanager.com/gtag/js?id=G-81C6JE60BQ"></script>
  <script>window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments);}gtag('js',new Date());gtag('config','G-81C6JE60BQ');</script>
</head>
<body>
  <header class="site-header">
    <div class="container inner">
      <a href="/" class="site-logo">
        <img src="/assets/images/logos/logo-dark.svg" alt="Alec Asgari" width="140" height="36">
      </a>
      <button class="nav-toggle" type="button" aria-label="Menu"><iconify-icon icon="lucide:menu"></iconify-icon></button>
      <nav>
        <ul class="site-nav">
          <li><a href="/">Home</a></li>
          <li><a href="/about.html">About Me</a></li>
          <li><a href="/case-studies.html">Case Studies</a></li>
          <li><a href="/projects.html">Projects</a></li>
          <li><a href="/blog.html" class="active">Blog</a></li>
          <li><a href="/contact.html">Contact</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <main>
    <section class="blog-detail-hero" style="background-image:url('${esc(image)}')">
      <div class="blog-detail-hero-overlay"></div>
      <div class="blog-detail-hero-mesh" aria-hidden="true"></div>
      <div class="container">
        <p class="eyebrow hero-in">
          <iconify-icon icon="lucide:newspaper"></iconify-icon>
          <a href="/blog.html">Blog</a> / ${esc(category)}
        </p>
        <div class="blog-detail-badges hero-in hero-in-d1">
          <span class="blog-badge blog-badge--category">${esc(category)}</span>
        </div>
        <h1 class="hero-in hero-in-d1">${esc(title)}</h1>
        <p class="blog-detail-excerpt hero-in hero-in-d2">${esc(excerpt)}</p>
        <div class="blog-detail-meta-row hero-in hero-in-d3">
          <div class="blog-detail-meta-item">
            <img src="${esc(author_image)}" alt="${esc(author)}" width="36" height="36">
            <span>${esc(author)}</span>
          </div>
          <div class="blog-detail-meta-item">
            <iconify-icon icon="lucide:calendar"></iconify-icon>
            <span>${esc(formatDate(date))}</span>
          </div>
        </div>
      </div>
    </section>

    <section class="section">
      <div class="container blog-detail-layout">
        <article class="blog-detail-content reveal">
          <div class="blog-prose">${bodyHtml}</div>
          ${tagsHtml}
          <div class="blog-author-box">
            <img src="${esc(author_image)}" alt="${esc(author)}" width="56" height="56">
            <div>
              <h3>${esc(author)}</h3>
              <p class="role">Author &amp; Content Creator</p>
              <p>Passionate about creating valuable content and sharing insights from real automation and CRM projects.</p>
            </div>
          </div>
        </article>

        <aside class="sidebar-panel blog-sidebar card-lift reveal">
          <h3><iconify-icon icon="lucide:info"></iconify-icon> Article Info</h3>
          <ul>
            <li><iconify-icon icon="lucide:folder"></iconify-icon><div><strong>Category</strong>${esc(category)}</div></li>
            <li><iconify-icon icon="lucide:calendar"></iconify-icon><div><strong>Published</strong>${esc(formatDate(date))}</div></li>
            <li><iconify-icon icon="lucide:user"></iconify-icon><div><strong>Author</strong>${esc(author)}</div></li>
          </ul>
          <a href="/blog.html" class="btn btn-outline btn-block" style="margin-top:1rem">
            <iconify-icon icon="lucide:arrow-left"></iconify-icon>
            All Articles
          </a>
          <a href="/contact.html" class="btn btn-primary btn-block" style="margin-top:0.5rem">
            <iconify-icon icon="lucide:mail"></iconify-icon>
            Get in Touch
          </a>
        </aside>
      </div>
    </section>

    <section class="section section-alt section-tight">
      <div class="container blog-detail-cta reveal">
        <a href="/blog.html" class="btn btn-outline">
          <iconify-icon icon="lucide:arrow-left"></iconify-icon>
          Back to Blog
        </a>
        <a href="/projects.html" class="btn btn-primary">
          <iconify-icon icon="lucide:folder-kanban"></iconify-icon>
          View Projects
        </a>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container inner">
      <a href="/" class="footer-logo"><img src="/assets/images/logos/logo-dark.svg" alt="Alec Asgari" width="120" height="32"></a>
      <p class="footer-copy">© 2025 Alec Asgari</p>
      <ul class="footer-links">
        <li><a href="https://www.linkedin.com/in/alecasgari/" target="_blank" rel="noopener"><iconify-icon icon="lucide:linkedin"></iconify-icon> LinkedIn</a></li>
        <li><a href="https://github.com/alecasgari" target="_blank" rel="noopener"><iconify-icon icon="lucide:github"></iconify-icon> GitHub</a></li>
        <li><a href="mailto:hello@alecasgari.com"><iconify-icon icon="lucide:mail"></iconify-icon> Email</a></li>
      </ul>
    </div>
  </footer>
  <script src="https://cdn.jsdelivr.net/npm/iconify-icon@1.0.8/dist/iconify-icon.min.js"></script>
  <script src="/assets/js/site-nav.js"></script>
  <script src="/assets/js/site-reveal.js"></script>
</body>
</html>`;
}

const referencesHtml = buildReferencesHtml(post);
const bodyHtml = mdToHtml(content) + referencesHtml;
const html = buildBlogHtml(post, bodyHtml, tags);

const blog_json_entry = {
  slug,
  title: post.title || 'Untitled',
  excerpt: post.excerpt || '',
  category: post.category || 'Business',
  date: String(post.date || '').slice(0, 10),
  image,
  url,
  author,
  author_image,
};

const blog_content_entry = {
  slug,
  body: bodyHtml,
  tags,
};

return [{
  json: {
    slug,
    linkedin_row_id: norm.linkedin_row_id,
    image_path: image,
    blog_url: `https://alecasgari.com${url}`,
    base64_html: Buffer.from(html, 'utf8').toString('base64'),
    blog_json_entry,
    blog_content_entry,
  },
}];

// n8n Code node: "Merge blog JSON"
// Input: GitHub Get blog.json

const prepared = $('Prepare Blog HTML for GitHub').first().json;
const entry = prepared.blog_json_entry;

if (!entry || !entry.slug) {
  throw new Error('blog_json_entry not found. Run Prepare Blog HTML for GitHub first.');
}

function parseGithubJson(item) {
  if (!item) return [];
  try {
    if (typeof item.content === 'string' && item.content) {
      const b64 = item.content.replace(/\s/g, '');
      return JSON.parse(Buffer.from(b64, 'base64').toString('utf8'));
    }
    if (item.content && typeof item.content === 'object' && item.content.content) {
      const b64 = String(item.content.content).replace(/\s/g, '');
      return JSON.parse(Buffer.from(b64, 'base64').toString('utf8'));
    }
    if (typeof item.data === 'string' && item.data) {
      return JSON.parse(item.data);
    }
  } catch (e) {
    return [];
  }
  return [];
}

let existing = parseGithubJson($input.first().json);
if (!Array.isArray(existing)) existing = [];

const filtered = existing.filter((p) => p.slug !== entry.slug);
filtered.unshift(entry);

const jsonText = JSON.stringify(filtered, null, 2) + '\n';
const base64_blog_json = Buffer.from(jsonText, 'utf8').toString('base64');

if (!base64_blog_json) {
  throw new Error('Failed to build base64_blog_json');
}

return [{
  json: {
    slug: entry.slug,
    linkedin_row_id: prepared.linkedin_row_id,
    blog_url: `https://alecasgari.com${entry.url}`,
    base64_blog_json,
  },
}];

// n8n Code node: "Merge blog content JSON"
// Input: GitHub Get blog-content.json

const prepared = $('Prepare Blog HTML for GitHub').first().json;
const entry = prepared.blog_content_entry;

if (!entry || !entry.slug) {
  throw new Error('blog_content_entry not found. Run Prepare Blog HTML for GitHub first.');
}

function parseGithubJson(item) {
  if (!item) return {};
  try {
    if (typeof item.content === 'string' && item.content) {
      const b64 = item.content.replace(/\s/g, '');
      return JSON.parse(Buffer.from(b64, 'base64').toString('utf8'));
    }
    if (item.content && typeof item.content === 'object' && item.content.content) {
      const b64 = String(item.content.content).replace(/\s/g, '');
      return JSON.parse(Buffer.from(b64, 'base64').toString('utf8'));
    }
    if (typeof item.data === 'string' && item.data) {
      return JSON.parse(item.data);
    }
  } catch (e) {
    return {};
  }
  return {};
}

let existing = parseGithubJson($input.first().json);
if (!existing || typeof existing !== 'object' || Array.isArray(existing)) existing = {};

existing[entry.slug] = {
  body: entry.body,
  tags: entry.tags || [],
};

const jsonText = JSON.stringify(existing, null, 2) + '\n';
const base64_blog_content_json = Buffer.from(jsonText, 'utf8').toString('base64');

if (!base64_blog_content_json) {
  throw new Error('Failed to build base64_blog_content_json');
}

return [{
  json: {
    slug: entry.slug,
    linkedin_row_id: prepared.linkedin_row_id,
    base64_blog_content_json,
  },
}];
